attempts.sql:
SELECT CASE WHEN EXISTS(
  SELECT 1
  FROM cards c
  JOIN sets s ON c.setCode = s.code
  WHERE c.name = 'Angel of Mercy' AND s.mtgoCode IS NOT NULL
) THEN 'Yes' ELSE 'No' END AS appeared_on_mtgo;

